<?php
declare(strict_types=1); require_once dirname(__DIR__).'/includes/auth.php'; require_once __DIR__.'/layout.php'; require_once dirname(__DIR__).'/services/batches.php';
$current=tuman_require_role('TEACHER');$error=null;$batches=[];try{$batches=tuman_teacher_batches(tuman_database(),$current['id']);}catch(Throwable $e){error_log($e->getMessage());$error='Batches cannot be loaded right now.';}tuman_teacher_page_start('Batches');
?>
<h1>Batches</h1><p>Organise students for a course, record their batch classes, and create one set of draft invoices.</p><p><a class="button" href="/Tuman/teacher/batch-create.php">Create batch</a></p><?php if($error):?><p role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php else:?><div style="overflow-x:auto"><table><thead><tr><th>Batch</th><th>Billing rule</th><th>Members</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($batches as $batch):?><tr><td><?=htmlspecialchars($batch['batch_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars(str_replace('_',' ',$batch['billing_mode']).' — '.tuman_currency_amount_label($batch['charge'],$batch['currency_code']),ENT_QUOTES,'UTF-8')?></td><td><?= (int)$batch['member_count']?></td><td><?=htmlspecialchars($batch['status'],ENT_QUOTES,'UTF-8')?></td><td><a href="/Tuman/teacher/batch-view.php?id=<?=(int)$batch['id']?>">Manage</a> · <a href="/Tuman/teacher/batch-edit.php?id=<?=(int)$batch['id']?>">Edit</a> · <a href="/Tuman/teacher/batch-invoice-create.php?id=<?=(int)$batch['id']?>">Draft invoices</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;tuman_teacher_page_end();
